import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:the_only/core/data/persistent_library.dart';
import 'package:the_only/main.dart';
void main(){testWidgets('renders unified shell with functional local sixth-section gate',(tester) async {SharedPreferences.setMockInitialValues({});final store=PersistentLibraryStore(await SharedPreferences.getInstance());await store.initialize();await tester.pumpWidget(TheOnlyApp(store:store));expect(find.text('The Only'),findsOneWidget);expect(find.text('Cinema'),findsWidgets);expect(find.text('Live TV'),findsOneWidget);expect(find.text('Sources'),findsOneWidget);expect(find.text('Resolvers'),findsOneWidget);expect(find.text('Tools / Providers'),findsOneWidget);expect(find.text('System Diagnostics'),findsNothing);await tester.tap(find.byKey(const Key('settings-button')));await tester.pumpAndSettle();expect(find.byKey(const Key('section-optional')),findsOneWidget);await tester.tap(find.byKey(const Key('section-optional')));await tester.pumpAndSettle();await tester.pageBack();await tester.pumpAndSettle();expect(find.text('System Diagnostics'),findsWidgets);await tester.tap(find.text('System Diagnostics').last);await tester.pumpAndSettle();expect(find.byKey(const Key('system-diagnostics-screen')),findsOneWidget);expect(find.text('Local device information only. No telemetry is uploaded.'),findsOneWidget);});}
